fn document_xml() -> String {
    format!(
        r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document {NS_DECLS}><w:body><w:p/>{}</w:body></w:document>"#,
        DEFAULT_SECTPR.replace(r#" xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main""#, "")
    )
}

