pub const NUMBERING_XML: &str = r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:numbering xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"></w:numbering>"#;

pub fn bullet_abstract(id: i32) -> String {
    let glyphs = [("\u{F0B7}", "Symbol"), ("o", "Courier New"), ("\u{F0A7}", "Wingdings")];
    let mut lv = String::new();
    for i in 0..9 {
        let (g, f) = glyphs[i % 3];
        let left = 720 * (i + 1);
        lv.push_str(&format!(
            r#"<w:lvl w:ilvl="{i}"><w:start w:val="1"/><w:numFmt w:val="bullet"/><w:lvlText w:val="{g}"/><w:lvlJc w:val="left"/><w:pPr><w:ind w:left="{left}" w:hanging="360"/></w:pPr><w:rPr><w:rFonts w:ascii="{f}" w:hAnsi="{f}" w:hint="default"/></w:rPr></w:lvl>"#
        ));
    }
    format!(r#"<w:abstractNum xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" w:abstractNumId="{id}"><w:multiLevelType w:val="hybridMultilevel"/>{lv}</w:abstractNum>"#)
}

pub fn decimal_abstract(id: i32) -> String {
    let fmts = ["decimal", "lowerLetter", "lowerRoman"];
    let mut lv = String::new();
    for i in 0..9 {
        let fmt = fmts[i % 3];
        let jc = if fmt == "lowerRoman" { "right" } else { "left" };
        let hanging = if fmt == "lowerRoman" { 180 } else { 360 };
        let left = 720 * (i + 1);
        lv.push_str(&format!(
            r#"<w:lvl w:ilvl="{i}"><w:start w:val="1"/><w:numFmt w:val="{fmt}"/><w:lvlText w:val="%{}."/><w:lvlJc w:val="{jc}"/><w:pPr><w:ind w:left="{left}" w:hanging="{hanging}"/></w:pPr></w:lvl>"#,
            i + 1
        ));
    }
    format!(r#"<w:abstractNum xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" w:abstractNumId="{id}"><w:multiLevelType w:val="hybridMultilevel"/>{lv}</w:abstractNum>"#)
}

pub fn blank_package() -> Package {
    let parts = vec![
        ("[Content_Types].xml", CONTENT_TYPES.to_string()),
        ("_rels/.rels", ROOT_RELS.to_string()),
        ("word/document.xml", document_xml()),
        ("word/_rels/document.xml.rels", DOC_RELS.to_string()),
        ("word/styles.xml", STYLES_XML.to_string()),
        ("word/settings.xml", SETTINGS.to_string()),
        ("word/fontTable.xml", FONT_TABLE.to_string()),
        ("word/theme/theme1.xml", THEME_XML.to_string()),
        ("docProps/core.xml", CORE.to_string()),
        ("docProps/app.xml", APP.to_string()),
    ];
    Package { parts: parts.into_iter().map(|(n, d)| Part { name: n.to_string(), data: d.into_bytes() }).collect() }
}
